function potionTextHTML(value){const part=potionNameBinding(value)||(value&&typeof value==='object'?_auxDisplayValues.get(value):null);return part?_auxInline(part.key,part.fallback,part.params):escape(value)}
function potionNameHTML(value,role='plain'){return potionTextHTML(potionNameRole(value,role))}
function potionNameAttribute(attribute,value,role){const part=potionNameBinding(value,role);return part?_auxAttribute(attribute,'"',part.key,part.fallback,part.params):escape(_potionRoles[role].replace('{name}',String(value)))}
function potionDescription(legacy,key,canonical,params={}){if(!potionReady()||globalThis.BOI18nCatalogs['en-US'][key]!==canonical)return legacy;const scalar=Object.fromEntries(Object.entries(params).map(([name,value])=>[name,potionNumber(value)])),value=new String(legacy);_potionDescriptions.set(value,[{key,source:canonical,params:scalar}]);return value}
function potionJoin(values,separator,suffix=''){const pieces=[];for(let i=0;i<values.length;i++){if(i)pieces.push(separator);pieces.push(...(values[i]&&typeof values[i]==='object'?_potionDescriptions.get(values[i])||[String(values[i])]:[String(values[i])]));}if(String(suffix))pieces.push(...(suffix&&typeof suffix==='object'?_potionDescriptions.get(suffix)||[String(suffix)]:[String(suffix)]));const legacy=values.map(String).join(separator)+String(suffix);if(!pieces.some(part=>typeof part==='object'))return legacy;const value=new String(legacy);_potionDescriptions.set(value,pieces);return value}
function potionDetail(oldKey,original,key,canonical,params={}){return potionDescription(_aux(oldKey,original,params),key,canonical,params)}
function potionRule(id,source,translatedLegacy=false){const known=_potionIDs.includes(id),key=translatedLegacy&&known?(_auxKeys[source]||globalThis.BOTranslation?.keyFor?.(source)):null,legacy=translatedLegacy&&key&&key!=='catalog.potions.'+id+'.description'?_aux(key,source):source;return known?potionDescription(legacy,'catalog.potions.'+id+'.description',source):legacy}
function potionRichHTML(text,key,params,money=false){
 const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),effect=value=>window.BOEffectText?.html?window.BOEffectText.html(value):escape(value),source=String(text??'');
 if(!money)return effect(source);
 const moneyToken=/[+−-]?\$[+−-]?(?:\d+(?:,\d{3})*(?:\.\d+)?|\.\d+)(?:e[+−-]?\d+|Qa|Qi|[KMBT])?/gi;
 let html='',start=0;for(const match of source.matchAll(moneyToken)){html+=effect(source.slice(start,match.index))+'<span class="money-amount">'+escape(match[0])+'</span>';start=match.index+match[0].length}return html+effect(source.slice(start));
}
function potionEffectHTML(value,format){const pieces=value&&typeof value==='object'?_potionDescriptions.get(value):null,input=pieces?String(value):value,raw=String(input??''),html=format(input);if(!pieces||!potionReady())return html;let money=false;if(html!==potionRichHTML(raw,null,null,false)){if(html!==potionRichHTML(raw,null,null,true))return html;money=true;}return pieces.map(part=>typeof part==='string'?potionRichHTML(part,null,null,money):'<span data-i18n-description="'+escape(part.key)+'" data-i18n-params="'+escape(JSON.stringify(part.params))+'" data-i18n-potion-style="'+(money?'money':'plain')+'">'+potionRichHTML(_aux(part.key,part.source,part.params),part.key,part.params,money)+'</span>').join('')}
